import sys
import json
import pandas as pd
import numpy as np

def to_float(x, nd=2):
    return round(float(x), nd)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTALS ----------
    total_rev_tw = df['Revenue_TW'].dropna().sum()
    total_rev_lw = df['Revenue_LW'].dropna().sum()
    total_rev_ly = df['Revenue_LY'].dropna().sum()
    total_units_tw = df['Units_TW'].dropna().sum()
    total_units_lw = df['Units_LW'].dropna().sum()
    total_orders_tw = df['Orders_TW'].dropna().sum()
    total_orders_lw = df['Orders_LW'].dropna().sum()

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(total_rev_tw),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(total_rev_lw),
        "formula": "sum(Revenue_LW)"
    })
    if total_rev_ly > 0:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": to_float(total_rev_ly),
            "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(total_units_tw, 0),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(total_units_lw, 0),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(total_orders_tw, 0),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(total_orders_lw, 0),
        "formula": "sum(Orders_LW)"
    })

    if total_rev_lw != 0:
        wow_total = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(wow_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if total_rev_ly != 0:
        yoy_total = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(yoy_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---------- TOP ENTITIES BY REVENUE_TW ----------
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": to_float(row['Revenue_TW']),
            "formula": "Revenue_TW"
        })

    # ---------- TOP ENTITIES BY SHARE ----------
    top_share = df.dropna(subset=['Share_Pct']).sort_values('Share_Pct', ascending=False).head(3)
    for _, row in top_share.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "share", "period": "TW",
            "value": to_float(row['Share_Pct'], 1),
            "formula": "Share_Pct"
        })

    # ---------- RANK 1 ENTITY ----------
    if 'Rank' in df.columns and df['Rank'].notna().any():
        rank1 = df.loc[df['Rank'].idxmin()]
        facts.append({
            "entity": rank1['Entity'], "metric": "rank", "period": "TW",
            "value": to_float(rank1['Rank'], 0),
            "formula": "min(Rank)"
        })

    # ---------- BIGGEST WoW GAINER / LOSER ----------
    wow_valid = df.dropna(subset=['WoW_Pct'])
    if not wow_valid.empty:
        gainer = wow_valid.loc[wow_valid['WoW_Pct'].idxmax()]
        loser = wow_valid.loc[wow_valid['WoW_Pct'].idxmin()]
        facts.append({
            "entity": gainer['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(gainer['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })
        facts.append({
            "entity": loser['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(loser['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---------- BIGGEST YoY GAINER / LOSER ----------
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if not yoy_valid.empty:
        gainer_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmax()]
        loser_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmin()]
        facts.append({
            "entity": gainer_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(gainer_y['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })
        facts.append({
            "entity": loser_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(loser_y['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # ---------- TOP ENTITIES BY UNITS_TW ----------
    top_units = df.dropna(subset=['Units_TW']).sort_values('Units_TW', ascending=False).head(3)
    for _, row in top_units.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "units", "period": "TW",
            "value": to_float(row['Units_TW'], 0),
            "formula": "Units_TW"
        })

    # ---------- TOP ENTITIES BY ORDERS_TW ----------
    top_orders = df.dropna(subset=['Orders_TW']).sort_values('Orders_TW', ascending=False).head(3)
    for _, row in top_orders.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "orders", "period": "TW",
            "value": to_float(row['Orders_TW'], 0),
            "formula": "Orders_TW"
        })

    # Limit to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
